'use strict';
let emailLoginMode=window.RIJAA_DEPLOYED===true,emailStep='form',emailChallenge='',emailAddress='',emailPurpose='',emailBusy=false,emailForgot=false;
const previousEmailLogin=loginHTML;
loginHTML=function(){if(!emailLoginMode)return previousEmailLogin();const isAdmin=/^\/admin\/?$/i.test(location.pathname),employee=loginType==='employee',title=isAdmin?'دخول إدارة رجعة':employee?'دخول الموظف':'دخول صاحب النشاط';return `<main class="auth-layout"><section><div class="brand"></div><div class="eyebrow">رجعة · مساحة نشاطك وفريقك</div><h1>${title}</h1><p>${isAdmin?'كود تحقق على بريد الإدارة المعتمد.':'جوالك لحفظ بياناتك، وبريدك للدخول واستعادة حسابك.'}</p><div class="notice mt">${isAdmin?'الدخول مخصص لإدارة المنصة.':'عميل الولاء يصدر بطاقته بالاسم ورقم الجوال فقط.'}</div></section><section class="panel auth-panel"><h2>${emailStep==='otp'?'تحقق من بريدك':emailForgot?'استعادة كلمة المرور':title}</h2>${!isAdmin&&emailStep==='form'?`<div class="segmented"><button type="button" class="${!employee?'active':''}" data-action="email-role" data-kind="owner">صاحب النشاط</button><button type="button" class="${employee?'active':''}" data-action="email-role" data-kind="employee">الموظف</button></div>`:''}${emailStep==='otp'?`<p class="sub">أرسلنا كودًا إلى <b dir="ltr">${esc(emailAddress)}</b>. صالح لمدة 10 دقائق.</p><form id="email-verify"><label class="field"><span>كود التحقق</span><input class="input otp" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required dir="ltr"></label>${['reset','invite'].includes(emailPurpose)?'<label class="field"><span>كلمة المرور الجديدة</span><input class="input" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label>':''}<p id="email-error" class="error"></p><button class="btn primary full" ${emailBusy?'disabled':''}>${emailBusy?'جارٍ التحقق…':'تأكيد والدخول'}</button></form><button class="btn quiet full mt" data-action="email-back">العودة</button>`:emailStep==='sent'?`<p class="sub">إذا كان البريد مسجلًا، ستصلك رسالة لاستعادة حسابك.</p><button class="btn secondary full mt" data-action="email-back">العودة للدخول</button>`:`<form id="email-request"><label class="field"><span>البريد الإلكتروني</span><input class="input" name="email" type="email" autocomplete="email" maxlength="254" required dir="ltr" value="${esc(emailAddress)}" ${isAdmin?'placeholder="بريد الإدارة"':''}></label>${!isAdmin&&!emailForgot?`<label class="field"><span>كلمة المرور</span><input class="input" name="password" type="password" autocomplete="${newBusiness?'new-password':'current-password'}" minlength="10" maxlength="128" required></label>`:''}${!isAdmin&&!employee&&!emailForgot?`<label class="new-business-option terms"><input type="checkbox" id="email-new-business" ${newBusiness?'checked':''}>نشاط جديد</label>${newBusiness?'<label class="field"><span>اسم صاحب النشاط</span><input class="input" name="name" maxlength="40" autocomplete="name" required></label><label class="field"><span>اسم النشاط</span><input class="input" name="business" maxlength="36" required></label><label class="field"><span>رقم الجوال</span><input class="input" name="phone" type="tel" dir="ltr" autocomplete="tel" placeholder="05xxxxxxxx" required></label>':''}`:''}<p id="email-error" class="error"></p><button class="btn primary full" ${emailBusy?'disabled':''}>${emailBusy?'جارٍ المتابعة…':isAdmin?'إرسال كود الدخول':emailForgot?'إرسال كود الاستعادة':newBusiness&&!employee?'إنشاء الحساب':'تسجيل الدخول'}</button></form>${!isAdmin?`<button class="btn quiet full mt" data-action="email-forgot">${emailForgot?'العودة للدخول':employee?'أول دخول أو نسيت كلمة المرور؟':'نسيت كلمة المرور؟'}</button>`:''}`}</section></main>`;};
const oldMailModal=modal;
modal=function(title,html,footer){if(false&&html.includes('id="employee-form"'))html=html.replace('<button type="submit"','<label class="field"><span>بريد الموظف</span><input class="input" name="email" type="email" autocomplete="email" dir="ltr" required></label><p class="sub">يدخل الموظف من صفحة الدخول ويختار «أول دخول» لتعيين كلمة مروره عبر كود البريد.</p><button type="submit"');return oldMailModal(title,html,footer);};
function emailAccept(j){acceptServer(j);publicPage='';emailStep='form';emailForgot=false;newBusiness=false;view=role==='staff'?'scan':role==='admin'?'accounts':'overview';render();}
window.addEventListener('change',e=>{if(e.target.id==='email-new-business'){emailAddress=document.querySelector('#email-request [name=email]').value;newBusiness=e.target.checked;render();}},true);
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!emailLoginMode||!b)return;const a=b.dataset.action;if(!['email-role','email-forgot','email-back','server-logout'].includes(a))return;if(a==='server-logout'){emailStep='form';emailForgot=false;emailAddress='';return;}e.preventDefault();e.stopImmediatePropagation();if(a==='email-role'){loginType=b.dataset.kind;newBusiness=false;emailForgot=false;}if(a==='email-forgot'){emailAddress=document.querySelector('#email-request [name=email]')?.value||emailAddress;emailForgot=!emailForgot;newBusiness=false;}if(a==='email-back'){emailStep='form';emailForgot=false;emailBusy=false;}render();},true);
window.addEventListener('submit',async e=>{const f=e.target;if(!emailLoginMode||!['email-request','email-verify','join-form','employee-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();if(emailBusy)return;emailBusy=true;const d=new FormData(f),submit=f.querySelector('button[type=submit],button.btn.primary');if(submit)submit.disabled=true;try{if(f.id==='email-request'){const kind=/^\/admin\/?$/i.test(location.pathname)?'admin':loginType==='employee'?'employee':'owner';emailAddress=String(d.get('email')).trim();emailPurpose=emailForgot?(kind==='employee'?'invite':'reset'):newBusiness?'register':kind==='admin'?'admin':'verify';const j=await api('/api/email/request',{kind,email:emailAddress,password:d.get('password'),register:newBusiness&&kind==='owner',reset:emailForgot,name:d.get('name'),business:d.get('business'),phone:d.get('phone')});if(j.principal){emailAccept(j);return;}emailChallenge=j.challenge;emailStep=j.step;emailBusy=false;render();}else if(f.id==='email-verify'){emailAccept(await api('/api/email/verify',{challenge:emailChallenge,code:d.get('code'),password:d.get('password')}));}else if(f.id==='join-form'){emailAccept(await api('/api/customer/enroll',{shop:db.shop,name:d.get('name'),phone:d.get('phone')}));}else{await serverCommand({action:'add-employee',name:d.get('name'),phone:d.get('phone'),username:d.get('username'),password:d.get('password')});document.querySelector('#modal').close();}}catch(error){const el=document.querySelector('#email-error,#employee-error,#join-error');if(el)el.textContent=error.message;else toast(error.message);}finally{emailBusy=false;document.querySelectorAll('#email-request button.btn.primary,#email-verify button.btn.primary').forEach(b=>b.disabled=false);if(submit)submit.disabled=false;}},true);
const beforeEmailRender=render;
render=function(){beforeEmailRender();if(!emailLoginMode)return;if(/^\/admin\/?$/i.test(location.pathname)&&publicPage==='login'){const intro=document.querySelector('.auth-layout>section>p');if(intro)intro.textContent='كود تحقق على بريد الإدارة المعتمد.';}document.querySelectorAll('.auth-layout>section>p').forEach(el=>{if(el.textContent.includes('برقم جواله'))el.textContent='الدخول بالإيميل وكلمة المرور. رقم الجوال لحفظ بياناتك فقط.';});if(role==='client'){document.querySelectorAll('.steps .step').forEach((el,i)=>{if(i===1)el.remove();});const name=document.querySelector('#join-form [name=name]');if(name){name.required=true;name.closest('label').querySelector('.muted')?.remove();}const bottom=document.querySelector('.phone-bottom');if(clientStage==='phone'&&bottom)bottom.textContent='لديك بطاقة؟ اطلب من الموظف استرجاعها.';}document.querySelectorAll('[data-action=wallet]').forEach(b=>{b.disabled=true;b.title='إضافة المحفظة قيد الربط';});};
render();
